def resolve_build_order(deps):
    graph = {}
    for pkg, ds in deps.items():
        graph.setdefault(pkg, [])
        for d in ds:
            graph.setdefault(d, [])
            graph[pkg].append(d)
    order = []
    visiting = set()
    visited = set()

    def visit(node):
        if node in visiting:
            raise ValueError("dependency cycle detected at " + node)
        if node in visited:
            return
        visiting.add(node)
        for dep in sorted(graph[node]):
            visit(dep)
        visiting.remove(node)
        visited.add(node)
        order.append(node)

    for node in sorted(graph):
        if node not in visited:
            visit(node)
    return order

import re

def compute_balances(transactions):
    balances = {}
    for tx in transactions:
        amount = tx["amount"]
        # Strict format check: one or more digits, optionally followed by '.' and 1-2 digits.
        if not re.fullmatch(r'\d+(\.\d{1,2})?', amount):
            raise ValueError("invalid amount")
        # Convert to integer cents exactly, without floating point.
        if '.' in amount:
            int_part, frac_part = amount.split('.')
            cents = int(int_part) * 100 + int(frac_part) * (10 if len(frac_part) == 1 else 1)
        else:
            cents = int(amount) * 100
        # Must be strictly positive.
        if cents <= 0:
            raise ValueError("amount must be positive")
        balances[tx["from"]] = balances.get(tx["from"], 0) - cents
        balances[tx["to"]] = balances.get(tx["to"], 0) + cents
    return balances

def merge_settings(defaults, overrides):
    result = dict(defaults)
    for key, value in overrides.items():
        if isinstance(value, dict) and isinstance(result.get(key), dict):
            result[key] = merge_settings(result[key], value)
        else:
            result[key] = value
    return result

def purge_expired(sessions, now):
    purged = [sid for sid, expiry in sessions.items() if expiry <= now]
    for sid in purged:
        del sessions[sid]
    return purged

class RateLimiter:
    def __init__(self, max_calls, window_seconds):
        self.max_calls = max_calls
        self.window = window_seconds
        self.calls = []

    def allow(self, timestamp):
        self.calls = [t for t in self.calls if timestamp - t < self.window]
        if len(self.calls) < self.max_calls:
            self.calls.append(timestamp)
            return True
        return False

from collections import OrderedDict
from typing import Any, Optional, Dict, Union

class TTLCache:
    """
    A fixed-capacity LRU cache with per-entry time-to-live (TTL),
    driven by an explicit logical clock, with operation statistics.
    """

    def __init__(self, capacity: int) -> None:
        if not isinstance(capacity, int) or capacity < 1:
            raise ValueError("capacity must be an integer >= 1")
        self._capacity = capacity
        self._cache: OrderedDict[Any, tuple] = OrderedDict()
        self._hits = 0
        self._misses = 0
        self._evictions = 0
        self._expirations = 0

    def _purge(self, now: Union[int, float]) -> None:
        """Remove all entries that are dead at `now`."""
        dead_keys = []
        for key, (_, stored_time, ttl) in self._cache.items():
            if ttl is not None and now >= stored_time + ttl:
                dead_keys.append(key)
        for key in dead_keys:
            del self._cache[key]
            self._expirations += 1

    def put(self, key: Any, value: Any, now: Union[int, float],
            ttl: Optional[Union[int, float]] = None) -> None:
        """
        Insert or update an entry.

        Raises ValueError if ttl is not None and ttl <= 0.
        """
        if ttl is not None and ttl <= 0:
            raise ValueError("ttl must be positive or None")

        self._purge(now)

        if key in self._cache:
            # Update existing entry: reset time and ttl, mark as MRU
            self._cache[key] = (value, now, ttl)
            self._cache.move_to_end(key)
        else:
            # New entry: evict LRU if at capacity
            if len(self._cache) >= self._capacity:
                self._cache.popitem(last=False)  # LRU
                self._evictions += 1
            self._cache[key] = (value, now, ttl)  # inserted as MRU

    def get(self, key: Any, now: Union[int, float]) -> Any:
        """Retrieve a value, or None if missing/expired."""
        self._purge(now)

        if key in self._cache:
            self._hits += 1
            self._cache.move_to_end(key)
            return self._cache[key][0]
        else:
            self._misses += 1
            return None

    def stats(self) -> Dict[str, int]:
        """Return cumulative statistics."""
        return {
            "hits": self._hits,
            "misses": self._misses,
            "evictions": self._evictions,
            "expirations": self._expirations,
        }

    def __len__(self) -> int:
        """Number of entries currently stored (including unpurged expired ones)."""
        return len(self._cache)

import heapq

class TaskScheduler:
    """A priority queue of unique task ids supporting reprioritization and cancellation.

    Higher priority is served first. Among equal priorities, tasks are served in FIFO
    order of their original submission. Reprioritizing a task does not change its FIFO position.
    """

    def __init__(self):
        self._heap = []          # min-heap of (-priority, seq, task_id)
        self._active = {}         # task_id -> (priority, seq)
        self._seq = 0             # global sequence counter for FIFO ordering

    def submit(self, task_id, priority):
        """Add a new active task. Raises ValueError if task_id is already active."""
        if task_id in self._active:
            raise ValueError(f"Task {task_id!r} is already active")
        self._seq += 1
        self._active[task_id] = (priority, self._seq)
        heapq.heappush(self._heap, (-priority, self._seq, task_id))

    def reprioritize(self, task_id, priority):
        """Change an active task's priority. Raises KeyError if not active.
        The old priority stops mattering immediately; FIFO position is unchanged.
        """
        if task_id not in self._active:
            raise KeyError(f"Task {task_id!r} is not active")
        old_priority, seq = self._active[task_id]
        if old_priority == priority:
            return  # no change needed
        self._active[task_id] = (priority, seq)
        heapq.heappush(self._heap, (-priority, seq, task_id))

    def cancel(self, task_id):
        """Remove an active task without serving it. Raises KeyError if not active."""
        if task_id not in self._active:
            raise KeyError(f"Task {task_id!r} is not active")
        del self._active[task_id]

    def pop(self):
        """Remove and return the highest priority task (ties: earliest submission).
        Raises IndexError if no tasks are active.
        """
        while self._heap:
            neg_priority, seq, task_id = heapq.heappop(self._heap)
            priority = -neg_priority
            if task_id in self._active and self._active[task_id] == (priority, seq):
                del self._active[task_id]
                return task_id
        raise IndexError("pop from empty scheduler")

    def peek(self):
        """Return the highest priority task without removing it.
        Raises IndexError if no tasks are active.
        """
        while self._heap:
            neg_priority, seq, task_id = self._heap[0]
            priority = -neg_priority
            if task_id in self._active and self._active[task_id] == (priority, seq):
                return task_id
            heapq.heappop(self._heap)  # discard stale entry
        raise IndexError("peek from empty scheduler")

    def priority_of(self, task_id):
        """Return the current priority of an active task. Raises KeyError if not active."""
        if task_id not in self._active:
            raise KeyError(f"Task {task_id!r} is not active")
        return self._active[task_id][0]

    def __len__(self):
        """Return the number of active tasks."""
        return len(self._active)

class UndoStack:
    """A LIFO stack of arbitrary Python values whose mutating operations can be undone."""

    def __init__(self):
        self._stack = []      # the actual values
        self._history = []    # stack of ('push', value) or ('pop', value)

    def push(self, x) -> None:
        """Push x onto the top of the stack."""
        self._stack.append(x)
        self._history.append(('push', x))

    def pop(self):
        """Remove and return the top value. Raise IndexError if empty."""
        if not self._stack:
            raise IndexError("pop from empty stack")
        x = self._stack.pop()
        self._history.append(('pop', x))
        return x

    def peek(self):
        """Return the top value without removing it. Raise IndexError if empty."""
        if not self._stack:
            raise IndexError("peek from empty stack")
        return self._stack[-1]

    def undo(self) -> None:
        """Reverse the most recent successful push or pop that hasn't been undone."""
        if not self._history:
            raise RuntimeError("nothing to undo")
        op, x = self._history.pop()
        if op == 'push':
            # Undo a push: the pushed value is on top, so remove it.
            self._stack.pop()
        else:  # op == 'pop'
            # Undo a pop: put the popped value back on top.
            self._stack.append(x)

    def __len__(self) -> int:
        """Return the number of values currently on the stack."""
        return len(self._stack)

class VersionedKV:
    """
    A key-value store with commit snapshots, point-in-time reads, and rollback.

    Keys must be hashable; values can be arbitrary objects.
    """

    def __init__(self):
        self._working = {}          # current mutable state
        self._history = []          # list of immutable snapshots (index 0 -> version 1)

    def set(self, key, value) -> None:
        """Write a key-value pair to the working state."""
        self._working[key] = value

    def delete(self, key) -> None:
        """Remove a key from the working state. Raises KeyError if absent."""
        if key not in self._working:
            raise KeyError(key)
        del self._working[key]

    def get(self, key):
        """Read a value from the working state. Raises KeyError if absent."""
        if key not in self._working:
            raise KeyError(key)
        return self._working[key]

    def has(self, key) -> bool:
        """Return True if the key is present in the working state."""
        return key in self._working

    def commit(self) -> int:
        """
        Snapshot the working state and return the new version number.
        A new version is created even if no changes were made.
        """
        self._history.append(self._working.copy())
        return len(self._history)

    def get_at(self, key, version):
        """
        Return the value of `key` in the snapshot `version`.
        Raises ValueError if version is out of range (1 <= version <= latest()).
        Raises KeyError if the snapshot exists but does not contain the key.
        """
        if not (1 <= version <= len(self._history)):
            raise ValueError(f"version {version} out of range (1..{len(self._history)})")
        snapshot = self._history[version - 1]
        if key not in snapshot:
            raise KeyError(key)
        return snapshot[key]

    def rollback(self, version) -> None:
        """
        Replace the working state with a copy of snapshot `version`.
        Version 0 means the empty initial state.
        Raises ValueError if version is out of range (0 <= version <= latest()).
        History is never destroyed: all committed versions remain readable.
        """
        if not (0 <= version <= len(self._history)):
            raise ValueError(f"version {version} out of range (0..{len(self._history)})")
        if version == 0:
            self._working = {}
        else:
            self._working = self._history[version - 1].copy()

    def latest(self) -> int:
        """Return the number of commits so far (0 if none)."""
        return len(self._history)

def summarize_by_category(rows):
    if not isinstance(rows, list):
        raise TypeError("rows must be a list")

    result = {}
    for i, row in enumerate(rows):
        if not isinstance(row, tuple) or len(row) != 3:
            raise TypeError(f"row {i}: each row must be a tuple of length 3")
        category, amount, refunded = row

        if not isinstance(category, str) or category == "":
            raise ValueError(f"row {i}: category must be a non-empty string")

        if isinstance(amount, bool) or not isinstance(amount, (int, float)):
            raise TypeError(f"row {i}: amount must be an int or float")

        if amount < 0:
            raise ValueError(f"row {i}: amount must be non-negative")

        if not isinstance(refunded, bool):
            raise TypeError(f"row {i}: refunded must be a bool")

        if category not in result:
            result[category] = {
                "count": 0,
                "gross": 0.0,
                "net": 0.0,
                "largest": 0.0,
            }

        summary = result[category]
        summary["count"] += 1
        amt = float(amount)
        summary["gross"] += amt
        if not refunded:
            summary["net"] += amt
        if amt > summary["largest"]:
            summary["largest"] = amt

    return result

def clamp_values(values, low, high):
    # 1. values must be a list
    if not isinstance(values, list):
        raise TypeError("values must be a list")

    # 2. bounds must be numbers (and not bool)
    if (isinstance(low, bool) or not isinstance(low, (int, float)) or
        isinstance(high, bool) or not isinstance(high, (int, float))):
        raise TypeError("bounds must be numbers")

    # 3. low must not exceed high
    if low > high:
        raise ValueError("low must not exceed high")

    # 4. scan elements, clamping valid ones and raising on the first invalid one
    result = []
    for i, v in enumerate(values):
        if isinstance(v, bool) or not isinstance(v, (int, float)):
            raise TypeError(f"index {i}")
        if v < low:
            result.append(low)
        elif v > high:
            result.append(high)
        else:
            result.append(v)

    return result

def flatten_depth(nested, max_depth):
    # Validation 1: nested must be a list
    if not isinstance(nested, list):
        raise TypeError("nested must be a list")
    # Validation 2: max_depth must be an int (and not a bool)
    if isinstance(max_depth, bool) or not isinstance(max_depth, int):
        raise TypeError("max_depth must be an int")
    # Validation 3: max_depth must be >= 0
    if max_depth < 0:
        raise ValueError("max_depth must be >= 0")

    result = []
    # Stack holds tuples of (item, remaining_depth)
    # Process elements of nested in reverse order so that left-to-right order is preserved
    stack = [(item, max_depth) for item in reversed(nested)]

    while stack:
        item, depth = stack.pop()
        if isinstance(item, list) and depth > 0:
            # Expand this list: push its elements in reverse order with depth-1
            for sub in reversed(item):
                stack.append((sub, depth - 1))
        else:
            # Atom or no remaining depth: keep as is
            result.append(item)

    return result

def render_template(template, context):
    if not isinstance(template, str):
        raise TypeError("template must be a string")
    if not isinstance(context, dict):
        raise TypeError("context must be a dict")

    out = []
    i = 0
    n = len(template)

    def valid_name_char(ch):
        return (
            ("A" <= ch <= "Z")
            or ("a" <= ch <= "z")
            or ("0" <= ch <= "9")
            or ch == "_"
        )

    while i < n:
        c = template[i]
        if c == "{":
            # Escape "{{" -> literal "{"
            if i + 1 < n and template[i + 1] == "{":
                out.append("{")
                i += 2
                continue
            # Placeholder
            j = i + 1
            if j >= n:
                raise ValueError(f"unclosed placeholder at position {i}")
            first = template[j]
            if first == "}":
                raise ValueError(f"empty placeholder at position {i}")
            if not valid_name_char(first):
                raise ValueError(f"invalid placeholder at position {i}")
            name_chars = []
            while j < n and valid_name_char(template[j]):
                name_chars.append(template[j])
                j += 1
            if j >= n:
                raise ValueError(f"unclosed placeholder at position {i}")
            if template[j] != "}":
                raise ValueError(f"invalid placeholder at position {i}")
            key = "".join(name_chars)
            if key not in context:
                raise KeyError(key)
            out.append(str(context[key]))
            i = j + 1
        elif c == "}":
            # Escape "}}" -> literal "}"
            if i + 1 < n and template[i + 1] == "}":
                out.append("}")
                i += 2
                continue
            raise ValueError(f"stray '}}' at position {i}")
        else:
            out.append(c)
            i += 1

    return "".join(out)

def eval_rpn(tokens):
    if not isinstance(tokens, list):
        raise TypeError("tokens must be a list")
    if len(tokens) == 0:
        raise ValueError("empty expression")

    stack = []
    for i, tok in enumerate(tokens):
        if not isinstance(tok, str):
            raise TypeError(f"token {i}")

        if tok in ("+", "-", "*", "/"):
            if len(stack) < 2:
                raise ValueError(f"stack underflow at token {i}")
            right = stack.pop()
            left = stack.pop()
            if tok == "+":
                stack.append(left + right)
            elif tok == "-":
                stack.append(left - right)
            elif tok == "*":
                stack.append(left * right)
            else:  # "/"
                if right == 0:
                    raise ZeroDivisionError(f"token {i}")
                # Integer division truncated toward zero (C-style)
                q = left // right
                if (left % right != 0) and ((left < 0) != (right < 0)):
                    q += 1
                stack.append(q)
        else:
            # Operand: optional single leading '+' or '-' followed by one or more ASCII digits
            if len(tok) == 0:
                raise ValueError(f"unknown token {i}")
            if tok[0] in ("+", "-"):
                if len(tok) == 1:
                    # Exactly "+" or "-" is an operator, already handled above.
                    raise ValueError(f"unknown token {i}")
                rest = tok[1:]
            else:
                rest = tok
            if len(rest) == 0 or not all('0' <= c <= '9' for c in rest):
                raise ValueError(f"unknown token {i}")
            stack.append(int(tok))

    if len(stack) != 1:
        raise ValueError("leftover operands")
    return stack[0]

def deep_get(data, path):
    if not isinstance(path, str):
        raise TypeError("path must be a string")
    if path == "":
        raise ValueError("path must not be empty")

    segments = path.split('.')

    def has_empty(segs):
        if not segs:
            return False
        if segs[0] == "":
            return True
        return has_empty(segs[1:])

    if has_empty(segments):
        raise ValueError("empty segment")

    def all_ascii_digits(s):
        if s == "":
            return True
        return s[0] in '0123456789' and all_ascii_digits(s[1:])

    def is_valid_int_literal(s):
        if s == "":
            return False
        if s[0] == '-':
            return len(s) > 1 and all_ascii_digits(s[1:])
        return all_ascii_digits(s)

    def navigate(node, segs):
        if not segs:
            return node
        seg = segs[0]
        rest = segs[1:]
        if isinstance(node, dict):
            if seg not in node:
                raise KeyError(seg)
            return navigate(node[seg], rest)
        elif isinstance(node, list):
            if not is_valid_int_literal(seg):
                raise ValueError("invalid index")
            index = int(seg)
            if index < -len(node) or index >= len(node):
                raise IndexError(seg)
            return navigate(node[index], rest)
        else:
            raise TypeError("cannot descend")

    return navigate(data, segments)

def top_k_frequent(items, k):
    # Validation 1: items must be a list
    if not isinstance(items, list):
        raise TypeError("items must be a list")
    # Validation 2: k must be an int (and not a bool)
    if isinstance(k, bool) or not isinstance(k, int):
        raise TypeError("k must be an int")
    # Validation 3: k must be >= 0
    if k < 0:
        raise ValueError("k must be >= 0")

    if k == 0:
        return []

    # Build frequency and first-occurrence index without mutating items
    freq = {}
    first_occurrence = {}
    for i, val in enumerate(items):
        if val not in freq:
            freq[val] = 0
            first_occurrence[val] = i
        freq[val] += 1

    distinct = list(freq.keys())
    result = []

    # Select top k by repeated manual selection (no sorted/min/max)
    for _ in range(min(k, len(distinct))):
        best_val = None
        best_count = -1
        best_first = None
        for val in distinct:
            c = freq[val]
            f = first_occurrence[val]
            if c > best_count or (c == best_count and f < best_first):
                best_val = val
                best_count = c
                best_first = f
        result.append((best_val, best_count))
        distinct.remove(best_val)

    return result
